const parseNode = $('Parse Golfers').item.json;
const player1 = parseNode.player1 || 'Field';
const player2 = parseNode.player2 || '';
const tournament = parseNode.tournament || 'PGA Tour';

let scoreboard = '{}';
let news = '[]';
let odds = '[]';

try { scoreboard = JSON.stringify($input.all()[0]?.json ?? {}); } catch(_) {}
try { news = JSON.stringify($input.all()[1]?.json ?? {}); } catch(_) {}
try { odds = JSON.stringify($input.all()[2]?.json ?? []); } catch(_) {}

// Extract top 10 outright odds
let oddsPayload = 'No odds available';
try {
  const oddsData = JSON.parse(odds);
  if (Array.isArray(oddsData) && oddsData.length > 0) {
    const bm = oddsData[0]?.bookmakers?.[0];
    const outrights = bm?.markets?.find(m => m.key === 'outrights');
    if (outrights?.outcomes) {
      const top10 = outrights.outcomes
        .sort((a, b) => a.price - b.price)
        .slice(0, 10)
        .map(o => `${o.name}: ${o.price > 0 ? '+' : ''}${o.price}`);
      oddsPayload = top10.join(' | ');
    }
  }
} catch(_) {}

// Extract leaderboard from ESPN
let leaderboard = 'Leaderboard unavailable';
try {
  const sb = JSON.parse(scoreboard);
  const comps = sb.events?.[0]?.competitions?.[0]?.competitors ?? [];
  if (comps.length > 0) {
    leaderboard = comps.slice(0, 15).map(c => {
      const name = c.athlete?.displayName ?? c.team?.displayName ?? 'Unknown';
      const score = c.score ?? 'E';
      const pos = c.status?.position?.displayName ?? '';
      return `${pos} ${name}: ${score}`;
    }).join(' | ');
  }
} catch(_) {}

return [{
  json: {
    player1,
    player2,
    tournament,
    leaderboard,
    espn_news: news.slice(0, 2000),
    odds_payload: oddsPayload
  }
}];
